/**
 * Saldo aus CB-Connect Account-Balance JSON (Deutsche Bank customerAccount-Format).
 */

export type CbConnectParsedBalance = {
  availableBalance: number;
  currentBalance: number;
  currency: string;
  /** Anzeige-Saldo (bevorzugt verfügbar) */
  balance: number;
};

function asNumber(v: unknown): number | null {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v === "string") {
    const n = Number.parseFloat(v.replace(",", "."));
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function pickBalanceAmount(
  obj: unknown
): { value: number; currency: string | null } | null {
  if (!obj || typeof obj !== "object") return null;
  const o = obj as Record<string, unknown>;
  const amount = o.balanceAmount;
  if (amount && typeof amount === "object") {
    const a = amount as Record<string, unknown>;
    const value = asNumber(a.value);
    if (value === null) return null;
    const currency =
      typeof a.currency === "string" ? a.currency.trim() : null;
    return { value, currency };
  }
  const direct = asNumber(o.value) ?? asNumber(o.amount) ?? asNumber(o.balance);
  if (direct === null) return null;
  const currency =
    typeof o.currency === "string" ? o.currency.trim() : null;
  return { value: direct, currency };
}

function parseCustomerAccount(
  customerAccount: Record<string, unknown>
): CbConnectParsedBalance | null {
  const currencyFallback =
    typeof customerAccount.accountCurrency === "string"
      ? customerAccount.accountCurrency.trim()
      : null;

  const balances = customerAccount.accountBalances;
  if (!balances || typeof balances !== "object") return null;

  const b = balances as Record<string, unknown>;
  const avail = pickBalanceAmount(b.availableBalance);
  const curr = pickBalanceAmount(b.currentBalance);

  const currency =
    avail?.currency ??
    curr?.currency ??
    currencyFallback ??
    "EUR";

  const availableBalance = avail?.value ?? curr?.value ?? 0;
  const currentBalance = curr?.value ?? avail?.value ?? 0;

  return {
    availableBalance,
    currentBalance,
    currency,
    balance: availableBalance,
  };
}

export function parseCbConnectBalanceFromBody(body: string): CbConnectParsedBalance {
  let json: unknown;
  try {
    json = JSON.parse(body) as unknown;
  } catch {
    return {
      availableBalance: 0,
      currentBalance: 0,
      currency: "EUR",
      balance: 0,
    };
  }

  if (!json || typeof json !== "object") {
    return {
      availableBalance: 0,
      currentBalance: 0,
      currency: "EUR",
      balance: 0,
    };
  }

  const root = json as Record<string, unknown>;

  const customerAccount = root.customerAccount;
  if (customerAccount && typeof customerAccount === "object") {
    const parsed = parseCustomerAccount(
      customerAccount as Record<string, unknown>
    );
    if (parsed) return parsed;
  }

  const directAvail = asNumber(root.availableBalance);
  const directCurr = asNumber(root.currentBalance);
  const direct = directAvail ?? directCurr ?? asNumber(root.balance);
  if (direct !== null) {
    const currency =
      typeof root.currency === "string"
        ? root.currency.trim()
        : typeof root.accountCurrency === "string"
          ? root.accountCurrency.trim()
          : "EUR";
    return {
      availableBalance: directAvail ?? direct,
      currentBalance: directCurr ?? direct,
      currency,
      balance: directAvail ?? directCurr ?? direct,
    };
  }

  return {
    availableBalance: 0,
    currentBalance: 0,
    currency: "EUR",
    balance: 0,
  };
}

import {
  basicAuthHeader,
  httpsRequest,
  mtlsRequest,
  truncateErrorBody,
} from "./cb-connect-http";
import {
  applyAccountBalanceUrlPlaceholders,
  createAccountBalanceCorrelationId,
  createStatementCorrelationId,
  formatCbConnectApiTimestamp,
} from "./cb-connect-signing-core";
import {
  createCbConnectSigner,
  formatCbConnectGmtDate,
  parseCbConnectHealthStatus,
} from "./cb-connect-signature";
import type { NativeBankResolvedCredentials } from "./resolved-credentials";

function pfxBuffer(creds: NativeBankResolvedCredentials): Buffer {
  return Buffer.from(creds.certificateBase64, "base64");
}

function mtlsOpts(creds: NativeBankResolvedCredentials) {
  return {
    pfx: pfxBuffer(creds),
    passphrase: creds.certificatePassword,
  };
}

/** Wie BC GetAccessToken — POST ohne mTLS, nur Basic Auth. */
export async function cbConnectFetchAccessToken(
  creds: NativeBankResolvedCredentials,
  tokenUrl: string
): Promise<{ accessToken: string; expiresInSec?: number }> {
  const url = tokenUrl.trim();
  if (!url) throw new Error("Token-URL fehlt.");

  const res = await httpsRequest({
    url,
    method: "POST",
    headers: {
      Authorization: basicAuthHeader(creds.clientId, creds.clientSecret),
      Accept: "application/json",
    },
  });

  if (res.status < 200 || res.status >= 300) {
    throw new Error(
      `Token-Anfrage fehlgeschlagen (HTTP ${res.status}): ${truncateErrorBody(res.body)}`
    );
  }

  let json: { access_token?: string; expires_in?: number; error?: string };
  try {
    json = JSON.parse(res.body) as typeof json;
  } catch {
    throw new Error("Token-Antwort ist kein gültiges JSON.");
  }

  if (!json.access_token) {
    const err =
      typeof json.error === "string" && json.error
        ? json.error
        : truncateErrorBody(res.body) || "access_token fehlt";
    throw new Error(err);
  }

  return {
    accessToken: json.access_token,
    expiresInSec:
      typeof json.expires_in === "number" ? json.expires_in : undefined,
  };
}

/**
 * Signierter GET (wie BC GetHealth / DownlaodCertificate):
 * Date, Signature, Bearer, optional keyId — plus mTLS.
 */
export async function cbConnectSignedGet(
  creds: NativeBankResolvedCredentials,
  url: string,
  accessToken: string,
  extraHeaders?: Record<string, string>
): Promise<{ status: number; body: string }> {
  const target = url.trim();
  if (!target) throw new Error("URL fehlt.");

  const dateHeader = formatCbConnectGmtDate();
  const signer = createCbConnectSigner(
    pfxBuffer(creds),
    creds.certificatePassword
  );
  const { signatureHeader } = signer.signGet(
    target,
    dateHeader,
    creds.keyId
  );

  const headers: Record<string, string> = {
    Date: dateHeader,
    Signature: signatureHeader,
    Authorization: `Bearer ${accessToken}`,
    Accept: "application/json",
    ...extraHeaders,
  };

  if (creds.keyId.trim()) {
    headers.keyId = creds.keyId.trim();
  }

  const res = await mtlsRequest({
    url: target,
    method: "GET",
    headers,
    ...mtlsOpts(creds),
  });

  if (res.status < 200 || res.status >= 300) {
    throw new Error(
      `API-Anfrage fehlgeschlagen (HTTP ${res.status}): ${truncateErrorBody(res.body)}`
    );
  }

  return { status: res.status, body: res.body };
}

/** Signierter GET — liefert Status/Body auch bei HTTP-Fehlern (für Statement-Polling). */
export async function cbConnectSignedGetResult(
  creds: NativeBankResolvedCredentials,
  url: string,
  accessToken: string,
  extraHeaders?: Record<string, string>
): Promise<{ status: number; body: string }> {
  const target = url.trim();
  if (!target) throw new Error("URL fehlt.");

  const dateHeader = formatCbConnectGmtDate();
  const signer = createCbConnectSigner(
    pfxBuffer(creds),
    creds.certificatePassword
  );
  const { signatureHeader } = signer.signGet(
    target,
    dateHeader,
    creds.keyId
  );

  const headers: Record<string, string> = {
    Date: dateHeader,
    Signature: signatureHeader,
    Authorization: `Bearer ${accessToken}`,
    Accept: "application/json",
    ...extraHeaders,
  };

  if (creds.keyId.trim()) {
    headers.keyId = creds.keyId.trim();
  }

  const res = await mtlsRequest({
    url: target,
    method: "GET",
    headers,
    ...mtlsOpts(creds),
  });

  return { status: res.status, body: res.body };
}

/** Health-Check wie BC GetHealth — status muss „UP“ sein. */
export async function cbConnectGetHealth(
  creds: NativeBankResolvedCredentials,
  healthUrl: string,
  accessToken: string
): Promise<{ status: number; body: string; healthStatus: string }> {
  const result = await cbConnectSignedGet(creds, healthUrl, accessToken);
  const healthStatus = parseCbConnectHealthStatus(result.body);

  if (healthStatus !== "UP") {
    throw new Error(
      healthStatus
        ? `Health-Status ist „${healthStatus}“, erwartet „UP“.`
        : `Health-Antwort enthält kein status=UP: ${truncateErrorBody(result.body)}`
    );
  }

  return { ...result, healthStatus };
}

/** Kontosaldo — signierter GET mit Query-Platzhaltern (%1–%3). */
export async function cbConnectFetchAccountBalance(
  creds: NativeBankResolvedCredentials,
  balanceUrlTemplate: string,
  accessToken: string,
  params: {
    branchIdentifier: string;
    accountCurrency: string;
    accountIdentifier: string;
  }
): Promise<{
  status: number;
  body: string;
  resolvedUrl: string;
  correlationId: string;
}> {
  const resolvedUrl = applyAccountBalanceUrlPlaceholders(
    balanceUrlTemplate.trim(),
    params.branchIdentifier,
    params.accountCurrency,
    params.accountIdentifier
  );

  const correlationId = createAccountBalanceCorrelationId();

  const result = await cbConnectSignedGet(creds, resolvedUrl, accessToken, {
    "x-customer-identifier": creds.xCustomerIdentifier,
    "x-correlation-identifier": correlationId,
    "x-apiConsumer-request-timestamp": formatCbConnectApiTimestamp(),
  });

  return { ...result, resolvedUrl, correlationId };
}

function bankingRequestHeaders(
  creds: NativeBankResolvedCredentials,
  correlationId: string,
  extra?: Record<string, string>
): Record<string, string> {
  return {
    "x-customer-identifier": creds.xCustomerIdentifier,
    "x-correlation-identifier": correlationId,
    "x-apiConsumer-request-timestamp": formatCbConnectApiTimestamp(),
    ...extra,
  };
}

/** Kontoauszug anfordern — signierter POST auf Statements-Request-URL. */
export async function cbConnectRequestStatement(
  creds: NativeBankResolvedCredentials,
  requestUrl: string,
  accessToken: string,
  body: string,
  options?: { apiVersion?: string }
): Promise<{
  status: number;
  body: string;
  correlationId: string;
}> {
  const correlationId = createStatementCorrelationId();
  const version = (options?.apiVersion ?? "").trim();
  const extraHeaders = bankingRequestHeaders(creds, correlationId, {
    ...(version ? { "x-api-version": version } : {}),
  });

  const result = await cbConnectSignedPost(
    creds,
    requestUrl,
    accessToken,
    body,
    extraHeaders
  );

  return { ...result, correlationId };
}

/** Kontoauszug laden (CAMT) — signierter GET auf Statements-Load-URL. */
export async function cbConnectLoadStatement(
  creds: NativeBankResolvedCredentials,
  loadUrl: string,
  accessToken: string,
  options?: { apiVersion?: string; allowErrorStatus?: boolean }
): Promise<{
  status: number;
  body: string;
  correlationId: string;
}> {
  const correlationId = createStatementCorrelationId();
  const version = (options?.apiVersion ?? "").trim();
  const extraHeaders = bankingRequestHeaders(creds, correlationId, {
    Accept: "application/xml, application/json, text/plain, */*",
    ...(version ? { "x-api-version": version } : {}),
  });

  const result = options?.allowErrorStatus
    ? await cbConnectSignedGetResult(creds, loadUrl, accessToken, extraHeaders)
    : await cbConnectSignedGet(creds, loadUrl, accessToken, extraHeaders);

  return { ...result, correlationId };
}

/**
 * Signierter POST (für spätere Zertifikats-/Zahlungs-APIs).
 * Digest-Header wird gesetzt wie in BC CertificateSigning.
 */
export async function cbConnectSignedPost(
  creds: NativeBankResolvedCredentials,
  url: string,
  accessToken: string,
  body: string,
  extraHeaders?: Record<string, string>
): Promise<{ status: number; body: string }> {
  const target = url.trim();
  if (!target) throw new Error("URL fehlt.");

  const dateHeader = formatCbConnectGmtDate();
  const signer = createCbConnectSigner(
    pfxBuffer(creds),
    creds.certificatePassword
  );
  const { signatureHeader, digestHeader } = signer.signPost(
    target,
    body,
    dateHeader,
    creds.keyId
  );

  const headers: Record<string, string> = {
    Date: dateHeader,
    Signature: signatureHeader,
    Digest: digestHeader,
    Authorization: `Bearer ${accessToken}`,
    Accept: "application/json",
    "Content-Type": "application/json",
    "Content-Length": String(Buffer.byteLength(body, "utf8")),
    ...extraHeaders,
  };

  if (creds.keyId.trim()) {
    headers.keyId = creds.keyId.trim();
  }

  const res = await mtlsRequest({
    url: target,
    method: "POST",
    headers,
    body,
    ...mtlsOpts(creds),
  });

  if (res.status < 200 || res.status >= 300) {
    throw new Error(
      `API-Anfrage fehlgeschlagen (HTTP ${res.status}): ${truncateErrorBody(res.body)}`
    );
  }

  return { status: res.status, body: res.body };
}

function buildCbConnectSignedPostHeaders(
  creds: NativeBankResolvedCredentials,
  url: string,
  accessToken: string | null,
  body: string,
  extraHeaders?: Record<string, string>,
  options?: { omitAuthorization?: boolean }
): Record<string, string> {
  const target = url.trim();
  const dateHeader = formatCbConnectGmtDate();
  const signer = createCbConnectSigner(
    pfxBuffer(creds),
    creds.certificatePassword
  );
  const { signatureHeader, digestHeader } = signer.signPost(
    target,
    body,
    dateHeader,
    creds.keyId
  );

  const headers: Record<string, string> = {
    Date: dateHeader,
    Signature: signatureHeader,
    Digest: digestHeader,
    Accept: "application/json",
    "Content-Type": "application/json",
    "Content-Length": String(Buffer.byteLength(body, "utf8")),
    ...extraHeaders,
  };

  if (!options?.omitAuthorization && accessToken) {
    headers.Authorization = `Bearer ${accessToken}`;
  }

  if (creds.keyId.trim()) {
    headers.keyId = creds.keyId.trim();
  }

  return headers;
}

/** Signierter POST — liefert Status/Body auch bei HTTP-Fehlern (Probes). */
export async function cbConnectSignedPostResult(
  creds: NativeBankResolvedCredentials,
  url: string,
  accessToken: string | null,
  body: string,
  extraHeaders?: Record<string, string>,
  options?: { omitAuthorization?: boolean }
): Promise<{ status: number; body: string; requestHeaders: Record<string, string> }> {
  const target = url.trim();
  if (!target) throw new Error("URL fehlt.");

  const headers = buildCbConnectSignedPostHeaders(
    creds,
    target,
    accessToken,
    body,
    extraHeaders,
    options
  );

  const res = await mtlsRequest({
    url: target,
    method: "POST",
    headers,
    body,
    ...mtlsOpts(creds),
  });

  return { status: res.status, body: res.body, requestHeaders: headers };
}

export type CbConnectSwiftTrackerHeaderParams = {
  branchIdentifier: string;
  accountIdentifier: string;
  clientBic: string;
  correlationId: string;
};

/** SWIFT GPI / Tracker Status — signierter POST (CB-Connect-Standard + SWIFT-Header). */
export async function cbConnectSwiftTrackerStatusPost(
  creds: NativeBankResolvedCredentials,
  url: string,
  accessToken: string,
  body: string,
  headerParams: CbConnectSwiftTrackerHeaderParams,
  options?: { allowErrorStatus?: boolean }
): Promise<{
  status: number;
  body: string;
  correlationId: string;
  requestHeaders?: Record<string, string>;
}> {
  const extraHeaders = bankingRequestHeaders(
    creds,
    headerParams.correlationId,
    {
      branchIdentifier: headerParams.branchIdentifier.trim(),
      accountIdentifier: headerParams.accountIdentifier.trim(),
      clientBIC: headerParams.clientBic.trim(),
    }
  );

  if (options?.allowErrorStatus) {
    const res = await cbConnectSignedPostResult(
      creds,
      url,
      accessToken,
      body,
      extraHeaders
    );
    return { ...res, correlationId: headerParams.correlationId };
  }

  const res = await cbConnectSignedPost(creds, url, accessToken, body, extraHeaders);

  return { ...res, correlationId: headerParams.correlationId };
}

import https from "node:https";
import { URL } from "node:url";

import { readCbconTlsInsecure } from "./env-config";
import { extractCaPemsFromP12 } from "./p12-tls";

const DEFAULT_TIMEOUT_MS = 35_000;

export type MtlsOptions = {
  pfx: Buffer;
  passphrase: string;
  /** Zusätzliche CA-PEMs; Standard: alle Zertifikate aus dem P12. */
  caPems?: string[];
  /** true = rejectUnauthorized false (nur Sandbox). */
  insecure?: boolean;
};

function resolveMtlsTlsOptions(mtls: MtlsOptions): {
  ca?: string | string[];
  rejectUnauthorized: boolean;
} {
  const fromP12 =
    mtls.caPems ?? extractCaPemsFromP12(mtls.pfx, mtls.passphrase).caPems;
  const insecure = mtls.insecure ?? readCbconTlsInsecure();
  return {
    ...(fromP12.length > 0 ? { ca: fromP12 } : {}),
    rejectUnauthorized: !insecure,
  };
}

export function formatTlsError(err: unknown): string {
  const msg = err instanceof Error ? err.message : String(err);
  if (
    msg.includes("unable to get local issuer certificate") ||
    msg.includes("self-signed certificate") ||
    msg.includes("UNABLE_TO_VERIFY_LEAF_SIGNATURE")
  ) {
    return (
      "TLS: Das Server-Zertifikat von api.sbx.baas.db.com wird von Node.js nicht vertraut. " +
      "Für lokale Sandbox-Tests in .env.local setzen: CBCON_TLS_INSECURE=true " +
      "(oder Bank-CA-Zertifikat ins PKCS#12 aufnehmen). Original: " +
      msg
    );
  }
  return msg;
}

export type MtlsResponse = {
  status: number;
  body: string;
  headers: Record<string, string>;
};

function normalizeHeaders(
  raw: NodeJS.Dict<string | string[] | undefined>
): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(raw)) {
    if (v === undefined) continue;
    out[k.toLowerCase()] = Array.isArray(v) ? v.join(", ") : v;
  }
  return out;
}

export function httpsRequest(options: {
  url: string;
  method: "GET" | "POST";
  headers?: Record<string, string>;
  body?: string;
  mtls?: MtlsOptions;
  timeoutMs?: number;
}): Promise<MtlsResponse> {
  const u = new URL(options.url);
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;

  const tlsOptions: https.RequestOptions = {
    hostname: u.hostname,
    port: u.port ? Number(u.port) : 443,
    path: `${u.pathname}${u.search}`,
    method: options.method,
    headers: options.headers,
    rejectUnauthorized: true,
  };

  if (options.mtls) {
    tlsOptions.pfx = options.mtls.pfx;
    tlsOptions.passphrase = options.mtls.passphrase;
    Object.assign(tlsOptions, resolveMtlsTlsOptions(options.mtls));
  }

  return new Promise((resolve, reject) => {
    const req = https.request(
      tlsOptions,
      (res) => {
        const chunks: Buffer[] = [];
        res.on("data", (chunk: Buffer) => chunks.push(chunk));
        res.on("end", () => {
          resolve({
            status: res.statusCode ?? 0,
            body: Buffer.concat(chunks).toString("utf8"),
            headers: normalizeHeaders(res.headers),
          });
        });
      }
    );

    req.on("error", (err) => reject(new Error(formatTlsError(err))));
    req.setTimeout(timeoutMs, () => {
      req.destroy(new Error("Zeitüberschreitung bei der API-Anfrage."));
    });

    if (options.body) req.write(options.body);
    req.end();
  });
}

/** HTTPS mit Client-Zertifikat (mTLS). */
export function mtlsRequest(
  options: {
    url: string;
    method: "GET" | "POST";
    headers?: Record<string, string>;
    body?: string;
    timeoutMs?: number;
  } & MtlsOptions
): Promise<MtlsResponse> {
  const { url, method, headers, body, timeoutMs, pfx, passphrase, caPems, insecure } =
    options;
  return httpsRequest({
    url,
    method,
    headers,
    body,
    timeoutMs,
    mtls: { pfx, passphrase, caPems, insecure },
  });
}

export function basicAuthHeader(clientId: string, clientSecret: string): string {
  const token = Buffer.from(`${clientId}:${clientSecret}`, "utf8").toString(
    "base64"
  );
  return `Basic ${token}`;
}

export function truncateErrorBody(body: string, max = 280): string {
  const t = body.replace(/\s+/g, " ").trim();
  if (!t) return "";
  return t.length <= max ? t : `${t.slice(0, max)}…`;
}

import forge from "node-forge";

import {
  buildCbConnectSignatureHeader,
  buildCbConnectSigningInput,
  resolveCbConnectSignatureKeyId,
} from "./cb-connect-signing-core";
import { getPrivateKeyFromP12 } from "./p12-key";

export {
  buildCbConnectSigningInput,
  buildCbConnectSignatureHeader,
  formatCbConnectGmtDate,
  parseCbConnectHealthStatus,
  resolveCbConnectSignatureKeyId,
} from "./cb-connect-signing-core";

export function signCbConnectPayload(
  signingInput: string,
  privateKey: forge.pki.PrivateKey
): string {
  const md = forge.md.sha256.create();
  md.update(signingInput, "utf8");
  const signature = (privateKey as forge.pki.rsa.PrivateKey).sign(md);
  return forge.util.encode64(signature);
}

export function createCbConnectSigner(
  pfx: Buffer,
  passphrase: string
): {
  signGet(url: string, dateHeader: string, corporateSealKeyId: string): {
    dateHeader: string;
    signatureHeader: string;
  };
  signPost(
    url: string,
    body: string,
    dateHeader: string,
    corporateSealKeyId: string
  ): {
    dateHeader: string;
    signatureHeader: string;
    digestHeader: string;
  };
} {
  const privateKey = getPrivateKeyFromP12(pfx, passphrase);

  return {
    signGet(url, dateHeader, corporateSealKeyId) {
      const { signingInput } = buildCbConnectSigningInput({
        url,
        method: "GET",
        dateHeader,
      });
      const signatureBase64 = signCbConnectPayload(signingInput, privateKey);
      return {
        dateHeader,
        signatureHeader: buildCbConnectSignatureHeader({
          keyId: resolveCbConnectSignatureKeyId(corporateSealKeyId),
          method: "GET",
          signatureBase64,
        }),
      };
    },
    signPost(url, body, dateHeader, corporateSealKeyId) {
      const { signingInput, digestHeader } = buildCbConnectSigningInput({
        url,
        method: "POST",
        dateHeader,
        body,
      });
      if (!digestHeader) {
        throw new Error("Digest für POST-Signatur fehlt.");
      }
      const signatureBase64 = signCbConnectPayload(signingInput, privateKey);
      return {
        dateHeader,
        digestHeader,
        signatureHeader: buildCbConnectSignatureHeader({
          keyId: resolveCbConnectSignatureKeyId(corporateSealKeyId),
          method: "POST",
          signatureBase64,
        }),
      };
    },
  };
}

import { createHash, randomUUID } from "node:crypto";
import { URL } from "node:url";

/** Wie BC: Prefix + CreateGuid ohne { } und -. */
export function createCbConnectCorrelationId(prefix: string): string {
  return prefix + randomUUID().replace(/[{}-]/g, "");
}

/** Account-Balance / Kontenabfragen (BC: ACID + Guid). */
export function createAccountBalanceCorrelationId(): string {
  return createCbConnectCorrelationId("ACID");
}

/** Statement-Request (BC: STMT + Guid ohne { } und -). */
export function createStatementCorrelationId(): string {
  return createCbConnectCorrelationId("STMT");
}

/** Zertifikats-CSR / Renewal (BC: CMSR + Guid ohne { } und -). */
export function createCertificateCorrelationId(): string {
  return createCbConnectCorrelationId("CMSR");
}

/** Account Pre-Validation (BC: PREV + Guid ohne { } und -). */
export function createAccountPreValidationCorrelationId(): string {
  return createCbConnectCorrelationId("PREV");
}

/** FX4Cash HTTP-Header-Präfix (Sandbox/Postman: PYMT + Guid). */
export const FX4CASH_CORRELATION_PREFIX = "PYMT";

/** FX4Cash Zahlungsinitiierung (Sandbox: PYMT + Guid). */
export function createFx4CashCorrelationId(): string {
  return createCbConnectCorrelationId(FX4CASH_CORRELATION_PREFIX);
}

/** Guid für endToEndIdentification (ohne PYMT-Präfix). */
export function createFx4CashPaymentGuid(): string {
  return randomUUID().replace(/[{}-]/g, "").toUpperCase();
}

/** Neues Paar: Body-E2E + Header x-correlation-identifier (PYMT + E2E). */
export function createFx4CashCorrelationPair(): {
  correlationId: string;
  endToEndIdentification: string;
} {
  const endToEndIdentification = createFx4CashPaymentGuid();
  return {
    endToEndIdentification,
    correlationId: FX4CASH_CORRELATION_PREFIX + endToEndIdentification,
  };
}

/**
 * Koppelt E2E (pain.001) und Correlation-Header wie im DB-Referenz-curl:
 * x-correlation-identifier = PYMT + endToEndIdentification.
 */
export function resolveFx4CashCorrelationPair(
  endToEndIdentification?: string | null
): { correlationId: string; endToEndIdentification: string } {
  const raw = endToEndIdentification?.trim();
  if (!raw) {
    return createFx4CashCorrelationPair();
  }

  const normalized = raw.replace(/[{}-\s]/g, "").toUpperCase();
  const bodyE2e = normalized.startsWith(FX4CASH_CORRELATION_PREFIX)
    ? normalized.slice(FX4CASH_CORRELATION_PREFIX.length)
    : normalized;

  return {
    endToEndIdentification: bodyE2e,
    correlationId: FX4CASH_CORRELATION_PREFIX + bodyE2e,
  };
}

/** Wie BC getCurrentUtcTime: 2024-10-02T15:34:32Z */
export function formatCbConnectApiTimestamp(date = new Date()): string {
  const pad = (n: number) => String(n).padStart(2, "0");
  return (
    `${date.getUTCFullYear()}-` +
    `${pad(date.getUTCMonth() + 1)}-` +
    `${pad(date.getUTCDate())}T` +
    `${pad(date.getUTCHours())}:` +
    `${pad(date.getUTCMinutes())}:` +
    `${pad(date.getUTCSeconds())}Z`
  );
}

const LF = "\n";

/** Wie BC APIHelper.GetCurrentGMTTime — HTTP-date (RFC 7231). */
export function formatCbConnectGmtDate(date = new Date()): string {
  return date.toUTCString();
}

export function buildCbConnectSigningInput(options: {
  url: string;
  method: "GET" | "POST";
  dateHeader: string;
  body?: string;
}): { signingInput: string; digestHeader?: string } {
  const method = options.method.toLowerCase();
  const u = new URL(options.url);
  const requestTarget = `${u.pathname}${u.search}`;

  let signingInput =
    `date: ${options.dateHeader}${LF}` +
    `(request-target): ${method} ${requestTarget}`;

  if (method === "post") {
    const body = options.body ?? "";
    const hash = createHash("sha256").update(body, "utf8").digest("base64");
    const digestHeader = `SHA-256=${hash}`;
    signingInput += `${LF}digest: ${digestHeader}`;
    return { signingInput, digestHeader };
  }

  return { signingInput };
}

export function buildCbConnectSignatureHeader(options: {
  keyId: string;
  method: "GET" | "POST";
  signatureBase64: string;
}): string {
  const keyId = options.keyId.trim() || "undefined";
  let header =
    `keyId="${keyId}",algorithm="rsa-sha256",headers="date (request-target)`;
  if (options.method.toLowerCase() === "post") {
    header += " digest";
  }
  header += `",signature="${options.signatureBase64}"`;
  return header;
}

export function resolveCbConnectSignatureKeyId(
  corporateSealKeyId: string
): string {
  return corporateSealKeyId.trim() || "undefined";
}

/** BC-URL mit %1 / %2 / %3 für branchIdentifier, accountCurrency, accountIdentifier. */
export function applyAccountBalanceUrlPlaceholders(
  template: string,
  branchIdentifier: string,
  accountCurrency: string,
  accountIdentifier: string
): string {
  const enc = (v: string) => encodeURIComponent(v);
  return template
    .replace(/%1/g, enc(branchIdentifier))
    .replace(/%2/g, enc(accountCurrency))
    .replace(/%3/g, enc(accountIdentifier));
}

export function formatProbeResponseJson(body: string): string {
  try {
    return JSON.stringify(JSON.parse(body) as unknown, null, 2);
  } catch {
    return body;
  }
}

/** Request-Header für Probe-UI (Bearer gekürzt). */
export function formatProbeRequestHeaders(
  headers: Record<string, string>
): string {
  const masked: Record<string, string> = {};
  for (const key of Object.keys(headers).sort()) {
    const value = headers[key] ?? "";
    if (key.toLowerCase() === "authorization" && value.startsWith("Bearer ")) {
      const token = value.slice(7);
      masked[key] = `Bearer ${token.slice(0, 8)}${token.length > 8 ? "…" : ""}`;
    } else {
      masked[key] = value;
    }
  }
  return JSON.stringify(masked, null, 2);
}

export function parseCbConnectHealthStatus(body: string): string | null {
  try {
    const json = JSON.parse(body) as { status?: string };
    return typeof json.status === "string" ? json.status : null;
  } catch {
    return null;
  }
}

