/**
 * Deutsche Bank CB-Connect — Bootstrap aus Server-Env (.env.local).
 * Nur serverseitig; Werte nie an den Client zurückgeben (außer nicht-sensitive IDs).
 */

export type CbconEnvCredentials = {
  clientId: string;
  keyId: string;
  clientSecret: string;
  xCustomerIdentifier: string;
  certificateBase64: string;
  certificatePassword: string;
};

function env(key: string): string {
  const direct = (process.env[key] ?? "").trim();
  if (direct) return direct;
  // .env mit Leerzeichen vor dem Key: " CBCON_CLIENTID=…"
  for (const [k, v] of Object.entries(process.env)) {
    if (k.trim() === key && typeof v === "string") return v.trim();
  }
  return "";
}

/** Liest CBCON_* inkl. bekannter Schreibvarianten (CERTTIFICATE, PASSWORT). */
export function readCbconEnv(): CbconEnvCredentials {
  return {
    clientId: env("CBCON_CLIENTID"),
    keyId: env("CBCON_KEYID"),
    clientSecret: env("CBCON_CLIENTSECRET"),
    xCustomerIdentifier: env("CBCON_XCUSTOMERIDENTIFIER"),
    certificateBase64:
      env("CBCON_CERTIFICATEBASE64") || env("CBCON_CERTTIFICATEBASE64"),
    certificatePassword:
      env("CBCON_CERTIFICATEPASSWORD") || env("CBCON_CERTIFICATEPASSWORT"),
  };
}

/** Nur Sandbox/Dev: TLS-Serverprüfung abschalten (Node kennt DB-CA nicht). */
export function readCbconTlsInsecure(): boolean {
  const v = env("CBCON_TLS_INSECURE").toLowerCase();
  return v === "1" || v === "true" || v === "yes";
}

export function hasCbconEnv(): boolean {
  const e = readCbconEnv();
  return Boolean(
    e.clientId ||
      e.keyId ||
      e.clientSecret ||
      e.xCustomerIdentifier ||
      e.certificateBase64 ||
      e.certificatePassword
  );
}

import forge from "node-forge";

/** Privater Schlüssel aus PKCS#12 (für CB-Connect HTTP-Signatur). */
export function getPrivateKeyFromP12(
  pfx: Buffer,
  passphrase: string
): forge.pki.PrivateKey {
  const der = forge.util.createBuffer(pfx.toString("binary"));
  const asn1 = forge.asn1.fromDer(der);
  const p12 = forge.pkcs12.pkcs12FromAsn1(asn1, passphrase);

  const shrouded = p12.getBags({ bagType: forge.pki.oids.pkcs8ShroudedKeyBag });
  const shroudedBag =
    shrouded[forge.pki.oids.pkcs8ShroudedKeyBag]?.[0]?.key;
  if (shroudedBag) return shroudedBag;

  const plain = p12.getBags({ bagType: forge.pki.oids.keyBag });
  const plainBag = plain[forge.pki.oids.keyBag]?.[0]?.key;
  if (plainBag) return plainBag;

  throw new Error(
    "Kein privater Schlüssel im PKCS#12 gefunden (Signatur nicht möglich)."
  );
}

import forge from "node-forge";

export type P12TlsMaterial = {
  /** PEM-Zertifikate aus dem P12 (inkl. CA-Kette) für Server-Trust. */
  caPems: string[];
};

/** CA-/Client-Zertifikate aus PKCS#12 für Node-TLS (mTLS + ggf. Issuer-Trust). */
export function extractCaPemsFromP12(
  pfx: Buffer,
  passphrase: string
): P12TlsMaterial {
  const der = forge.util.createBuffer(pfx.toString("binary"));
  const asn1 = forge.asn1.fromDer(der);
  const p12 = forge.pkcs12.pkcs12FromAsn1(asn1, passphrase);

  const caPems: string[] = [];
  const certBags = p12.getBags({ bagType: forge.pki.oids.certBag });
  for (const bag of certBags[forge.pki.oids.certBag] ?? []) {
    if (bag.cert) {
      caPems.push(forge.pki.certificateToPem(bag.cert));
    }
  }

  return { caPems };
}

