      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(30_000),
    }
  );

  if (!res.ok) {
    const body = await readErrorBody(res);
    throw new FinapiApiError(
      `finAPI Web Form fehlgeschlagen (HTTP ${res.status})`,
      res.status,
