import { randomUUID } from "node:crypto";
import {
  FinapiApiError,
  finapiCreateBankConnectionWebForm,
  finapiCreatePaymentWithAccountWebForm,
  finapiCreateStandalonePaymentWebForm,
  finapiCreateUser,
  finapiFetchAccountTransactions,
  finapiFetchAccounts,
